-- Bagwise: dot overlay
-- Blizzard bags (combined and separate), Baganator corner widgets,
-- EllesmereUI Bags and Bagnon.

Bagwise = Bagwise or {}
Bagwise.Overlay = {}

-- Colour is baked into each texture (a pearl sphere with its own highlight and
-- soft shadow), so the dots are painted untinted. Generated by
-- tools/make_dot_textures.py.
local TEXTURES = {
  green  = "Interface\\AddOns\\Bagwise\\textures\\dot_green",
  yellow = "Interface\\AddOns\\Bagwise\\textures\\dot_yellow",
}

-- The frame includes the shadow margin; the visible sphere is about 78%, sitting high in the frame of it.
local DOT_SIZE = 13

-- ---------------------------------------------------------------------------
-- Shared helpers
-- ---------------------------------------------------------------------------
local function makeDot(parent)
  local dot = parent:CreateTexture(nil, "OVERLAY")
  dot:SetSize(DOT_SIZE, DOT_SIZE)
  dot:SetVertexColor(1, 1, 1, 1)
  return dot
end

-- Glow for the slots to delete while making room for loot: a green wash, a
-- solid frame and a ring that breathe slowly together (about 1.2 seconds a
-- cycle, far below any flash threshold, and never fully off). Nothing else moves.
-- Blizzard's own action-button border: it ships with every client, so it
-- cannot go missing the way an addon file can. It is a light glow with the
-- colour left to us, so it is tinted green and added onto the slot.
local GLOW_TEXTURE = "Interface\\Buttons\\UI-ActionButton-Border"
local GLOW_COLOR = { 0.25, 1.0, 0.45 }
local GLOW_SCALE = 1.9 -- frame size as a multiple of the slot, matches the texture
local GLOW_LOW_ALPHA = 0.35 -- never fades out, so the slot always stands out
local GLOW_SECONDS = 0.6
-- A green wash over the whole slot, so the item reads as lit from a distance,
-- plus a solid frame so the edge is crisp. The ring alone was too faint.
local GLOW_FILL_ALPHA = 0.4
local GLOW_FRAME_THICKNESS = 2
local glowByButton = setmetatable({}, { __mode = "k" })

local function addBreathing(texture)
  if not texture.CreateAnimationGroup then return nil end
  local group = texture:CreateAnimationGroup()
  group:SetLooping("BOUNCE")
  local fade = group:CreateAnimation("Alpha")
  fade:SetDuration(GLOW_SECONDS)
  fade:SetSmoothing("IN_OUT")
  -- Mainline takes from/to alpha, older clients a change amount.
  if fade.SetFromAlpha then
    fade:SetFromAlpha(1)
    fade:SetToAlpha(GLOW_LOW_ALPHA)
  elseif fade.SetChange then
    fade:SetChange(GLOW_LOW_ALPHA - 1)
  end
  return group
end

local function colouredLayer(button, alpha)
  local texture = button:CreateTexture(nil, "OVERLAY")
  texture:SetColorTexture(GLOW_COLOR[1], GLOW_COLOR[2], GLOW_COLOR[3], alpha)
  return texture
end

local function makeGlow(button)
  local layers = {}

  -- The soft ring, added on top of itself for strength.
  for _ = 1, 2 do
    local ring = button:CreateTexture(nil, "OVERLAY")
    ring:SetTexture(GLOW_TEXTURE)
    ring:SetBlendMode("ADD")
    ring:SetVertexColor(GLOW_COLOR[1], GLOW_COLOR[2], GLOW_COLOR[3], 1)
    ring:SetPoint("CENTER", button, "CENTER", 0, 0)
    local size = (button.GetWidth and button:GetWidth() or 37) * GLOW_SCALE
    ring:SetSize(size, size)
    layers[#layers + 1] = ring
  end

  -- The wash over the icon.
  local fill = colouredLayer(button, GLOW_FILL_ALPHA)
  fill:SetAllPoints(button)
  layers[#layers + 1] = fill

  -- A solid frame: four thin edges.
  local t = GLOW_FRAME_THICKNESS
  local edges = {
    { "TOPLEFT", "TOPRIGHT", nil, t },
    { "BOTTOMLEFT", "BOTTOMRIGHT", nil, t },
    { "TOPLEFT", "BOTTOMLEFT", t, nil },
    { "TOPRIGHT", "BOTTOMRIGHT", t, nil },
  }
  for _, edge in ipairs(edges) do
    local line = colouredLayer(button, 1)
    line:SetPoint(edge[1], button, edge[1], 0, 0)
    line:SetPoint(edge[2], button, edge[2], 0, 0)
    if edge[3] then line:SetWidth(edge[3]) else line:SetHeight(edge[4]) end
    layers[#layers + 1] = line
  end

  local groups = {}
  for _, layer in ipairs(layers) do groups[#groups + 1] = addBreathing(layer) or false end
  return { layers = layers, groups = groups }
end

--- Show or hide the delete glow on an item button. bagID and slotID say which
-- slot the glow is for, so it can be found and hidden when that slot changes.
local function applyGlow(button, on, bagID, slotID)
  local glow = glowByButton[button]
  if not on then
    if glow then
      glow.on = false
      for i, layer in ipairs(glow.layers) do
        if glow.groups[i] then glow.groups[i]:Stop() end
        layer:Hide()
      end
    end
    return
  end
  if not glow then
    glow = makeGlow(button)
    glowByButton[button] = glow
  end
  glow.on, glow.bag, glow.slot = true, bagID, slotID
  for i, layer in ipairs(glow.layers) do
    layer:Show()
    local group = glow.groups[i]
    if group and not group:IsPlaying() then group:Play() end
  end
end

local function applyDot(dot, result)
  -- quiet: a verdict held back while a make-room plan shows only the slots to delete.
  if result and result.verdict and not result.quiet then
    dot:SetTexture(TEXTURES[result.verdict])
    dot:Show()
    return true
  else
    dot:Hide()
    return false
  end
end

-- Dots we made on other addons' item buttons, kept off the buttons themselves:
-- writing custom keys onto a secure item button can taint it.
local dotsByButton = setmetatable({}, { __mode = "k" })

local function getButtonDot(button)
  local dot = dotsByButton[button]
  if dot then return dot end
  dot = makeDot(button)
  dot:SetPoint("TOPRIGHT", button, "TOPRIGHT", -1, -1)
  dotsByButton[button] = dot
  return dot
end

-- Item buttons are recycled, so every paint decides the dot from scratch.
local function paintButton(button, bagID, slotID)
  local result = nil
  if Bagwise.Bags.IsScanned(bagID) then
    result = Bagwise.Scanner.GetResult(bagID, slotID)
  end
  -- Never create a dot just to hide it; a recycled button may still hold one.
  if result or dotsByButton[button] then
    applyDot(getButtonDot(button), result)
  end
  applyGlow(button, result and result.glow and not result.quiet, bagID, slotID)
end

-- Blizzard's item template reads the bag from the button's parent frame.
local function bagIDOf(button)
  if button.GetBagID then return button:GetBagID() end
  local parent = button:GetParent()
  return parent and parent:GetID()
end

-- ---------------------------------------------------------------------------
-- Adapter 1: Blizzard bags
-- ---------------------------------------------------------------------------
-- Two generations of Blizzard bag code are in play:
--   Forever (Mainline code): bags can be combined into one frame,
--     ContainerFrameCombinedBags. Item buttons have no global names, and each
--     one knows its own bag and slot (GetBagID, GetID). Slots are not reversed.
--   Classic Era: one ContainerFrameN per bag, with buttons named
--     ContainerFrameNItemM, where M counts from the end (slot = size - M + 1).
local MAX_FRAMES = NUM_CONTAINER_FRAMES or 13

local bankPanelFrames = setmetatable({}, { __mode = "k" })

-- The item buttons of a bank panel, as an iterator of buttons. Normally the panel
-- lists them itself; if it cannot, its child frames that know their own tab and
-- slot are the buttons.
local function bankButtons(panel)
  local buttons = {}
  if panel.EnumerateValidItems then
    -- Bag frames yield (index, button); the bank panel yields its button pool,
    -- which is (button, true). Take whichever of the two is the frame.
    for first, second in panel:EnumerateValidItems() do
      local button = type(first) == "table" and first or second
      if type(button) == "table" then buttons[#buttons + 1] = button end
    end
  elseif panel.GetChildren then
    for _, child in ipairs({ panel:GetChildren() }) do
      if child.GetBankTabID and child.GetContainerSlotID then buttons[#buttons + 1] = child end
    end
  end
  return buttons
end

-- Forever's bank is Mainline's BankPanel: one tab at a time, drawn from a pool of
-- buttons that each know their own tab (bag ID) and slot.
local function paintEnumerated(frame)
  for _, button in ipairs(bankButtons(frame)) do
    local bagID = button.GetBankTabID and button:GetBankTabID() or bagIDOf(button)
    local slotID = button.GetContainerSlotID and button:GetContainerSlotID() or button:GetID()
    -- A tab the client draws is a bank bag, whatever number it has.
    Bagwise.Bags.NoteBankBag(bagID)
    paintButton(button, bagID, slotID)
  end
end

local function paintNamed(frame)
  local bagID = frame:GetID()
  local frameName = frame:GetName()
  if not (bagID and frameName) then return end

  local numSlots = C_Container.GetContainerNumSlots(bagID)
  for buttonIndex = 1, numSlots do
    local button = _G[frameName .. "Item" .. buttonIndex]
    if button then
      paintButton(button, bagID, numSlots - buttonIndex + 1)
    end
  end
end

-- IsVisible, not IsShown: a bag frame parked under a hidden parent (as when a
-- bag replacement takes over) can still report shown.
local function paintFrame(frame)
  if not (frame and frame:IsVisible()) then return end
  if frame.EnumerateValidItems or bankPanelFrames[frame] then
    -- A bank painting error must not stop the other bags; /bagwise bank shows it.
    local ok, err = pcall(paintEnumerated, frame)
    Bagwise.Overlay.lastBankError = (not ok) and tostring(err) or nil
  else
    paintNamed(frame)
  end
end

-- The bank's item panels, on clients with the tabbed bank (Forever): one panel
-- for the character bank, and on some builds another for the warband bank. The
-- usual names are tried first, then the children of BankFrame, since the exact
-- name is not something every build agrees on.
local function bankPanels()
  local found, seen = {}, {}
  local function add(panel)
    -- A panel counts when it can list its item buttons, or has child frames
    -- that are bank item buttons (see bankButtons).
    if type(panel) == "table" and (panel.EnumerateValidItems or panel.GetChildren) and not seen[panel] then
      seen[panel] = true
      bankPanelFrames[panel] = true
      found[#found + 1] = panel
    end
  end
  add(BankFrame and BankFrame.BankPanel)
  add(BankFrame and BankFrame.AccountBankPanel)
  add(_G.BankPanel)
  add(_G.AccountBankPanel)
  if BankFrame and BankFrame.GetChildren then
    for _, child in ipairs({ BankFrame:GetChildren() }) do
      if child.EnumerateValidItems then add(child) end
    end
  end
  return found
end

local function bankPanel() return bankPanels()[1] end


local function blizzardFrames()
  local frames = {}
  if ContainerFrameCombinedBags then
    frames[#frames + 1] = ContainerFrameCombinedBags
  end
  for frameIndex = 1, MAX_FRAMES do
    local frame = _G["ContainerFrame" .. frameIndex]
    if frame then frames[#frames + 1] = frame end
  end
  for _, panel in ipairs(bankPanels()) do frames[#frames + 1] = panel end
  return frames
end

-- Switching bank tab re-inits the pooled buttons with no bag event, so the bank
-- panel is repainted straight after its own redraw. Done once per panel, and
-- when the panel first shows up, since it may be created after Bagwise loads.
local hookedBankPanels = setmetatable({}, { __mode = "k" })
local BANK_REDRAWS = { "GenerateItemSlotsForSelectedTab", "RefreshAllItemsForSelectedTab" }

local function hookBankPanel()
  for _, panel in ipairs(bankPanels()) do
    if not hookedBankPanels[panel] then
      hookedBankPanels[panel] = true
      for _, name in ipairs(BANK_REDRAWS) do
        if type(panel[name]) == "function" then
          hooksecurefunc(panel, name, function() paintFrame(panel) end)
        end
      end
      -- The first draw can come before Bagwise has hooked the panel.
      if panel.HookScript then
        panel:HookScript("OnShow", function() paintFrame(panel) end)
      end
    end
  end
end

local function updateBlizzard()
  hookBankPanel()
  for _, frame in ipairs(blizzardFrames()) do
    paintFrame(frame)
  end
end

-- Blizzard refreshes its buttons through UpdateItems (item moved, split,
-- sorted). Repaint straight after so a dot never lingers on a moved item.
local function hookBlizzardUpdates()
  for _, frame in ipairs(blizzardFrames()) do
    if frame.UpdateItems then
      hooksecurefunc(frame, "UpdateItems", paintFrame)
    end
  end
end

-- ---------------------------------------------------------------------------
-- Adapter 2: Baganator
-- ---------------------------------------------------------------------------
-- Baganator also draws other characters' bags and banks (through Syndicator)
-- with the same buttons. Whenever it tells us which item it is showing, check
-- that it is the item in that real slot, so a remembered item is never judged
-- against a live slot that happens to share its number.
local function itemIDOfLink(link)
  local instant = (C_Item and C_Item.GetItemInfoInstant) or GetItemInfoInstant
  return instant and (instant(link)) or nil
end

local function showsLiveItem(details, bagID, slotID)
  if not details.itemLink then return true end
  local liveID = C_Container.GetContainerItemID(bagID, slotID)
  if not liveID then return false end
  local shownID = itemIDOfLink(details.itemLink)
  return shownID == nil or shownID == liveID
end

local function initBaganator()
  if not Baganator or not Baganator.API or not Baganator.API.RegisterCornerWidget then
    return false
  end

  -- onUpdate: called by Baganator whenever an item button is refreshed.
  -- details.itemLocation contains the bagID and slotIndex.
  local function onUpdate(dot, details)
    -- A button that shows something we do not judge (another character's item,
    -- an empty slot) must not keep a delete glow from what it showed before.
    local button = dot.GetParent and dot:GetParent()
    local function noGlow()
      if button and button.CreateTexture then applyGlow(button, false) end
      return false
    end
    if not details.itemLocation then return noGlow() end

    local bagID = details.itemLocation.bagID
    local slotID = details.itemLocation.slotIndex

    if not bagID or not slotID then return noGlow() end
    if not showsLiveItem(details, bagID, slotID) then return noGlow() end

    local result = Bagwise.Scanner.GetResult(bagID, slotID)
    if button and button.CreateTexture then
      applyGlow(button, result and result.glow and not result.quiet, bagID, slotID)
    end
    return applyDot(dot, result)
  end

  -- onInit: called once per item button to create the widget.
  -- Baganator will parent and position the returned frame.
  local function onInit(itemButton)
    local dot = makeDot(itemButton)
    -- Baganator handles the anchoring, so no SetPoint is needed here.
    return dot
  end

  -- RegisterCornerWidget(label, id, onUpdate, onInit, defaultPosition, isFast)
  local ok, err = pcall(
    Baganator.API.RegisterCornerWidget,
    "Bagwise", "bagwise", onUpdate, onInit,
    { corner = "top_right", priority = 1 }, true
  )

  if not ok then
    print("|cff54de7d[Bagwise]|r Baganator corner widget registration failed: " .. tostring(err))
  end

  return ok
end

-- ---------------------------------------------------------------------------
-- Adapter 3: EllesmereUI Bags
-- ---------------------------------------------------------------------------
-- A bag replacement with no plugin API. Its slots are item-template buttons
-- kept in a pool, and each button's parent frame carries the bag ID, the same
-- as Blizzard's. The pool is read from the module's internals, which are
-- underscore-private: if the author renames them the dots stop and nothing
-- else breaks. RefreshInventory is the window's own repaint, so hook it.
local function ellesmereSlotPool()
  local modules = EllesmereUI and EllesmereUI._ModuleNS
  local bags = modules and modules["EllesmereUIBags"]
  local internals = bags and bags._bagsInternals
  return internals and internals.itemSlots
end

local function paintEllesmere()
  local pool = ellesmereSlotPool()
  if not pool then return end

  for _, button in pairs(pool) do
    if type(button) == "table" and button.IsVisible and button:IsVisible() then
      paintButton(button, bagIDOf(button), button:GetID())
    end
  end
end

local function hookEllesmereUpdates()
  if EUI_Bags and EUI_Bags.RefreshInventory then
    hooksecurefunc(EUI_Bags, "RefreshInventory", paintEllesmere)
  end
end

-- ---------------------------------------------------------------------------
-- Adapter 4: Bagnon
-- ---------------------------------------------------------------------------
-- Bagnon builds every slot from one item class, Bagnon.Item, and refreshes a
-- slot through UpdateSecondary (older versions: UpdatePrimary or Update). Hook
-- that, the way Bagnon's own plugins do. The buttons are remembered so they
-- can be repainted when a scan finishes after Bagnon has already drawn them.
--
-- Bagnon also shows other characters' bags, the bank while you are away, and
-- the guild bank and void storage through the same class. Only your own live
-- bags may get a dot: a cached or guild slot has the same bag number as one of
-- yours but holds something else, so those are painted as silent instead.
local bagnonButtons = setmetatable({}, { __mode = "k" })

local function bagnonItemClass()
  return Bagnon and Bagnon.Item
end

-- Guild bank and void storage buttons share the item class but have no
-- cooldown or glow, which only container buttons (your bags and bank) have.
local function isBagnonContainerButton(button)
  return type(button.UpdateCooldown) == "function"
end

local function paintBagnon(button)
  bagnonButtons[button] = true
  local live = isBagnonContainerButton(button)
      and not (button.IsCached and button:IsCached())
  if live then
    paintButton(button, button:GetBag(), button:GetID())
  else
    paintButton(button, nil, nil)
  end
end

local function hookBagnonUpdates()
  local item = bagnonItemClass()
  if not item then return end
  local method = (item.UpdateSecondary and "UpdateSecondary")
      or (item.UpdatePrimary and "UpdatePrimary")
      or (item.Update and "Update")
  if method then hooksecurefunc(item, method, paintBagnon) end
end

local function repaintBagnon()
  for button in pairs(bagnonButtons) do
    if button.IsVisible and button:IsVisible() then paintBagnon(button) end
  end
end

-- ---------------------------------------------------------------------------
-- Loot window: with full bags, a red X on loot that is worth less than your junk
-- (skip it) and a green check on loot that is worth a slot. Shapes, not dots.
-- ---------------------------------------------------------------------------
local lootMarksByRow = setmetatable({}, { __mode = "k" })
-- Shapes as well as colours: a red X for skip, a green check for take.
local LOOT_ICONS = {
  leave = "Interface\\RaidFrame\\ReadyCheck-NotReady",
  take = "Interface\\RaidFrame\\ReadyCheck-Ready",
  consider = "Interface\\RaidFrame\\ReadyCheck-Ready",
  noroom = "Interface\\RaidFrame\\ReadyCheck-Ready",
}

-- A small mark in the row's corner: an X when this loot is not worth a slot,
-- a check when it is (including loot you must make room for by hand).
local function paintLootRow(row, slot)
  local decision = slot and Bagwise.Scanner.LootDecision(slot)
  local icon = decision and LOOT_ICONS[decision]
  local mark = lootMarksByRow[row]
  if not icon then
    if mark then mark:Hide() end
    return
  end
  if not mark then
    if not row.CreateTexture then return end
    mark = row:CreateTexture(nil, "OVERLAY")
    mark:SetSize(16, 16)
    mark:SetPoint("RIGHT", row, "RIGHT", -6, 0)
    lootMarksByRow[row] = mark
  end
  mark:SetTexture(icon)
  mark:Show()
end

-- One line above the loot window while bags are full: what to do, or why
-- nothing needs doing.
local banner

local function bannerFrame()
  if banner then return banner end
  if not CreateFrame then return nil end
  banner = CreateFrame("Frame", "BagwiseLootBanner", UIParent)
  banner:SetFrameStrata("DIALOG")
  banner:SetSize(250, 32)
  local background = banner:CreateTexture(nil, "BACKGROUND")
  background:SetAllPoints(banner)
  background:SetColorTexture(0, 0, 0, 0.8)
  banner.text = banner:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
  banner.text:SetPoint("CENTER")
  banner.text:SetWidth(230)
  banner:Hide()
  return banner
end

function Bagwise.Overlay.UpdateBanner()
  local text = Bagwise.MakeRoom.BannerText(Bagwise.Scanner.MakeRoomSummary())
  local frame = text and bannerFrame()
  if not frame then
    if banner then banner:Hide() end
    return
  end
  frame.text:SetText(text)
  frame:SetHeight((frame.text.GetStringHeight and frame.text:GetStringHeight() or 20) + 16)
  frame:ClearAllPoints()
  if LootFrame and LootFrame:IsShown() then
    frame:SetPoint("BOTTOM", LootFrame, "TOP", 0, 8)
  else
    frame:SetPoint("TOP", UIParent, "TOP", 0, -140)
  end
  frame:Show()
end

--- Repaint the loot window rows. Rows are recycled, so each one is decided
-- from scratch. Works with the Mainline scroll list and classic loot buttons.
function Bagwise.Overlay.UpdateLoot()
  Bagwise.Overlay.UpdateBanner()
  if not LootFrame then return end

  if LootFrame.ScrollBox and LootFrame.ScrollBox.ForEachFrame then
    LootFrame.ScrollBox:ForEachFrame(function(row)
      local slot = row.GetSlotIndex and row:GetSlotIndex() or row.slot
      paintLootRow(row, slot)
    end)
    return
  end

  for index = 1, (LOOTFRAME_NUMBUTTONS or 4) do
    local row = _G["LootButton" .. index]
    if row then paintLootRow(row, row.slot) end
  end
end

-- ---------------------------------------------------------------------------
-- Public API
-- ---------------------------------------------------------------------------

-- Every window that shows scanned bags and should trigger a rescan on open.
-- The entry point hooks OnShow on these.
function Bagwise.Overlay.BagWindows()
  local windows = blizzardFrames()
  if EUI_Bags then windows[#windows + 1] = EUI_Bags end
  return windows
end

--- What Bagwise sees of the Blizzard bank, for /bagwise bank.
-- @return table  list of lines
local function bankDiagnosticLines()
  local lines = {}
  local function add(text) lines[#lines + 1] = text end
  local panels = bankPanels()
  add("BankFrame: " .. (BankFrame and "found" or "missing")
      .. (BankFrame and BankFrame.IsShown and (BankFrame:IsShown() and ", shown" or ", hidden") or ""))
  add("Bank panels with item buttons: " .. #panels)
  for index, panel in ipairs(panels) do
    local count, sample = 0, {}
    for _, button in ipairs(bankButtons(panel)) do
      count = count + 1
      if #sample < 3 then
        local tab = button.GetBankTabID and button:GetBankTabID() or "no GetBankTabID"
        local slot = button.GetContainerSlotID and button:GetContainerSlotID() or "no GetContainerSlotID"
        local result = type(tab) == "number" and type(slot) == "number"
            and Bagwise.Scanner.GetResult(tab, slot)
        sample[#sample + 1] = "tab " .. tostring(tab) .. " slot " .. tostring(slot)
            .. (type(tab) == "number" and (Bagwise.Bags.IsScanned(tab) and " scanned" or " NOT scanned") or "")
            .. (result and (" verdict " .. tostring(result.verdict)) or " no result")
    end
    end
    add("  panel " .. index .. (panel.IsVisible and (panel:IsVisible() and " visible" or " hidden") or "")
        .. ", " .. count .. " buttons")
    for _, line in ipairs(sample) do add("    " .. line) end
  end
  local ids = Bagwise.Bags.BankBags()
  add("Bank bag IDs with slots: " .. (#ids > 0 and table.concat(ids, ", ") or "none"))
  local known, detail = {}, {}
  for id in pairs(Bagwise.Bags.BankIDSet()) do known[#known + 1] = id end
  table.sort(known)
  for _, id in ipairs(known) do
    local slots = C_Container and C_Container.GetContainerNumSlots and C_Container.GetContainerNumSlots(id)
    if (slots or 0) > 0 then detail[#detail + 1] = id .. "=" .. slots end
  end
  add("Slots per bank bag: " .. (#detail > 0 and table.concat(detail, ", ") or "none read"))
  local keys = {}
  if Enum and Enum.BagIndex then
    for name, id in pairs(Enum.BagIndex) do
      if tostring(name):find("Bank") then keys[#keys + 1] = name .. "=" .. id end
    end
    table.sort(keys)
  end
  add("Enum.BagIndex bank entries: " .. (#keys > 0 and table.concat(keys, ", ") or "none"))
  return lines
end

function Bagwise.Overlay.BankDiagnostics()
  local ok, lines = pcall(bankDiagnosticLines)
  if ok then
    if Bagwise.Overlay.lastBankError then
      lines[#lines + 1] = "Last bank paint error: " .. Bagwise.Overlay.lastBankError
    end
    return lines
  end
  return { "Diagnostics failed: " .. tostring(lines) }
end

--- Which bag UIs Bagwise can currently paint (for /bagwise status).
-- @return table  list of names
function Bagwise.Overlay.DetectedBagAddons()
  local found = {}
  if ContainerFrameCombinedBags then found[#found + 1] = "Blizzard combined bags" end
  if ContainerFrame1 then found[#found + 1] = "Blizzard separate bags" end
  if bankPanel() then found[#found + 1] = "Blizzard bank" end
  if Baganator and Baganator.API and Baganator.API.RegisterCornerWidget then
    found[#found + 1] = "Baganator"
  end
  if ellesmereSlotPool() then found[#found + 1] = "EllesmereUI Bags" end
  if bagnonItemClass() then found[#found + 1] = "Bagnon" end
  return found
end

function Bagwise.Overlay.Init()
  if not initBaganator() then
    -- If Baganator isn't loaded yet, wait for its ADDON_LOADED event.
    local f = CreateFrame("Frame")
    f:RegisterEvent("ADDON_LOADED")
    f:SetScript("OnEvent", function(self, event, addonName)
      if addonName == "Baganator" then
        initBaganator()
        self:UnregisterEvent("ADDON_LOADED")
      end
    end)
  end

  hookBlizzardUpdates()
  hookEllesmereUpdates()
  hookBagnonUpdates()
end

-- Hide any delete glow whose slot is no longer marked. A bag addon only tells us
-- about buttons it redraws, and an emptied slot (the junk was just deleted) may
-- not be redrawn at all, so the glow would stay on the empty slot.
local function clearStaleGlows()
  if not (Bagwise.Scanner and Bagwise.Scanner.GetResult) then return end
  for button, glow in pairs(glowByButton) do
    if glow.on then
      local result = glow.bag and Bagwise.Scanner.GetResult(glow.bag, glow.slot)
      if not (result and result.glow and not result.quiet) then applyGlow(button, false) end
    end
  end
end

function Bagwise.Overlay.UpdateAll()
  clearStaleGlows()
  updateBlizzard()
  paintEllesmere()
  repaintBagnon()
  -- Baganator only repaints a button when it refreshes it, so ask it to when
  -- our results changed (a dot moved to another slot). Not on every scan: a
  -- refresh resets Baganator's own borders and highlights.
  if Bagwise.Scanner.ResultsChanged and Bagwise.Scanner.ResultsChanged()
      and Baganator and Baganator.API and Baganator.API.RequestItemButtonsRefresh then
    pcall(Baganator.API.RequestItemButtonsRefresh)
  end
end
